begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.uid(n integer)returns uuid language sql immutable as $$select ('19120000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)
select pg_temp.uid(n),'authenticated','authenticated','rich-series-s191-'||n||'@veyocast.test','test',now(),now(),now(),'{}','{}'from generate_series(1,3)n;
insert into public.profiles(id,display_name)select pg_temp.uid(n),'Publisher test '||n from generate_series(1,3)n;
insert into public.tenants(id,name,slug,screen_limit)values(pg_temp.uid(10),'Publisher A','rich-series-s191-a',5),(pg_temp.uid(11),'Publisher B','rich-series-s191-b',5);
insert into public.tenant_settings(tenant_id)values(pg_temp.uid(10)),(pg_temp.uid(11));
insert into public.tenant_memberships(tenant_id,user_id,role)values(pg_temp.uid(10),pg_temp.uid(1),'tenant_owner'),(pg_temp.uid(11),pg_temp.uid(2),'tenant_owner'),(pg_temp.uid(10),pg_temp.uid(3),'tenant_viewer');
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)
select pg_temp.uid(n),pg_temp.uid(case when n=21 then 11 else 10 end),'image','Ready photo '||n,'photo.webp','image/webp','ready',
 'tenants/'||pg_temp.uid(case when n=21 then 11 else 10 end)||'/assets/'||pg_temp.uid(n)||'/original.webp',2048,repeat('a',64),1920,1080 from generate_series(20,23)n;
insert into public.media_variants(tenant_id,asset_id,variant_type,storage_path,mime_type,file_size_bytes,checksum_sha256,width,height)
select tenant_id,id,'original',storage_path,mime_type,file_size_bytes,checksum_sha256,width,height from public.media_assets where id in(pg_temp.uid(20),pg_temp.uid(21),pg_temp.uid(22));
insert into public.playlists(id,tenant_id,name,created_by,updated_by,default_fit_mode,default_transition,default_video_muted,default_background_color)
select pg_temp.uid(n),pg_temp.uid(case when n=33 then 11 else 10 end),'Playlist '||n,pg_temp.uid(case when n=33 then 2 else 1 end),pg_temp.uid(case when n=33 then 2 else 1 end),'cover','crossfade',false,'#03438a'from generate_series(30,33)n;
insert into public.screens(id,tenant_id,name)values(pg_temp.uid(40),pg_temp.uid(10),'Three zone screen'),(pg_temp.uid(41),pg_temp.uid(10),'Second batch screen'),(pg_temp.uid(42),pg_temp.uid(11),'Other screen');
create temporary table command_results(name text primary key,value jsonb);grant all on command_results to authenticated,service_role;
create function pg_temp.batch(p_operations jsonb,p_key integer,p_playlist integer default 30,p_revision bigint default null)returns jsonb language sql as $$select public.mutate_playlist_batch_v1(pg_temp.uid(p_playlist),coalesce(p_revision,(select revision from public.playlists where id=pg_temp.uid(p_playlist))),p_operations,pg_temp.uid(p_key))$$;
create function pg_temp.composition(p_main integer default 30,p_side integer default 31)returns jsonb language sql as $$select jsonb_build_object('schemaVersion',1,'orientation','portrait','layout','three','mainWidthPercent',70,'bottomHeightPercent',20,'zones',jsonb_build_array(jsonb_build_object('id','main','playlistId',pg_temp.uid(p_main)),jsonb_build_object('id','side','playlistId',pg_temp.uid(p_side)),jsonb_build_object('id','bottom','playlistId',pg_temp.uid(30))))$$;

insert into public.playlists(id,tenant_id,name,created_by,updated_by)select pg_temp.uid(n),pg_temp.uid(10),'Rich playlist '||n,pg_temp.uid(1),pg_temp.uid(1)from generate_series(35,38)n;
create temporary table typed_fixtures(name text primary key,document jsonb);grant select on typed_fixtures to authenticated;
insert into typed_fixtures values('studio','{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":true,"durationMs":45000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"row-0","primary":"Team 0","home":"Team 0","away":"Opponent 0","time":"14:00"},{"id":"row-1","primary":"Team 1","home":"Team 1","away":"Opponent 1","time":"14:00"},{"id":"row-2","primary":"Team 2","home":"Team 2","away":"Opponent 2","time":"14:00"},{"id":"row-3","primary":"Team 3","home":"Team 3","away":"Opponent 3","time":"14:00"},{"id":"row-4","primary":"Team 4","home":"Team 4","away":"Opponent 4","time":"14:00"},{"id":"row-5","primary":"Team 5","home":"Team 5","away":"Opponent 5","time":"14:00"},{"id":"row-6","primary":"Team 6","home":"Team 6","away":"Opponent 6","time":"14:00"},{"id":"row-7","primary":"Team 7","home":"Team 7","away":"Opponent 7","time":"14:00"},{"id":"row-8","primary":"Team 8","home":"Team 8","away":"Opponent 8","time":"14:00"},{"id":"row-9","primary":"Team 9","home":"Team 9","away":"Opponent 9","time":"14:00"},{"id":"row-10","primary":"Team 10","home":"Team 10","away":"Opponent 10","time":"14:00"},{"id":"row-11","primary":"Team 11","home":"Team 11","away":"Opponent 11","time":"14:00"},{"id":"row-12","primary":"Team 12","home":"Team 12","away":"Opponent 12","time":"14:00"},{"id":"row-13","primary":"Team 13","home":"Team 13","away":"Opponent 13","time":"14:00"},{"id":"row-14","primary":"Team 14","home":"Team 14","away":"Opponent 14","time":"14:00"},{"id":"row-15","primary":"Team 15","home":"Team 15","away":"Opponent 15","time":"14:00"},{"id":"row-16","primary":"Team 16","home":"Team 16","away":"Opponent 16","time":"14:00"}],"scale":100}}}}'::jsonb),('configuration','{"schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","themeId":"onzetrots-tv","orientation":"landscape","provider":"sportlink","title":"Stand","subtitle":"","overlay":25,"accent":"#03438a","layout":"full","scale":100,"align":"left","safeArea":4,"seconds":15,"rowsPerPage":8,"ledTheme":"blue","ledMoment":"live","ledSide":"unknown","titleScale":100,"scoreScale":100,"logoScale":100,"teamScale":100,"showBranding":true,"showSceneLabel":true,"showClock":true,"showTimeline":true,"timelineLimit":3,"backgroundFit":"contain","grunge":55,"animation":"rise"}'::jsonb);

insert into public.dynamic_data_sources(id,tenant_id,name,kind,status,provider_status,config_json)values(pg_temp.uid(300),pg_temp.uid(10),'Real test source','sportlink','active','ready','{}');
insert into public.dynamic_slides(id,tenant_id,name,slide_type,orientation,template_id,template_version_id,data_source_id,selection_mode,status,configuration_json)
select pg_temp.uid(301),pg_temp.uid(10),'Scoped standings','sport_standing','landscape',template.id,version.id,pg_temp.uid(300),'latest','draft',
 '{"schemaVersion":1,"blueprintKey":"sportlink.pool_standings","title":"Poulestand","context":{"competitionId":null,"competitionSelectionMode":"auto_current","phaseId":null,"poolId":null,"providerTeamId":"jo17","seasonId":null},"display":{"columns":"two","showDressingRoom":false,"showField":true,"showHomeAway":true,"showReferee":false},"editorial":{"schemaVersion":2,"themeSelection":{"ref":{"catalog":"v2","id":"fieldflow","version":"1.0.0"},"modePolicy":{"kind":"fixed","mode":"light"},"accent":null,"support":null,"categoryOverrides":[]}},"maxItems":40}'::jsonb
from public.dynamic_templates template join public.dynamic_template_versions version on version.id=template.current_published_version_id where template.slide_type='sport_standing'and template.orientation='landscape'and template.status='published'limit 1;
insert into public.dynamic_slide_snapshots(id,tenant_id,dynamic_slide_id,template_version_id,data_source_id,source_revision_hash,snapshot_data_json,status,output_media_asset_id,completed_at)
select pg_temp.uid(302),tenant_id,id,template_version_id,data_source_id,repeat('a',64),'{"type":"sport_standing","sport":{"title":"Frozen standings","items":[]}}','ready',pg_temp.uid(20),now()from public.dynamic_slides where id=pg_temp.uid(301);
update public.dynamic_slides set current_snapshot_id=pg_temp.uid(302),status='ready'where id=pg_temp.uid(301);
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_dynamic','clientId',pg_temp.uid(310),'dynamicSlideId',pg_temp.uid(301),'expectedSnapshotId',pg_temp.uid(302),'durationSeconds',3)),311,35)$$,'a reviewed ready dynamic snapshot accepts a three-second explicit budget');
select is((select duration_seconds from public.playlist_items where playlist_id=pg_temp.uid(35)),3,'dynamic budget survives legacy defaults');
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','patch','itemId',(select id from public.playlist_items where playlist_id=pg_temp.uid(35)),'patch',jsonb_build_object('sitesConfiguration',(select document from typed_fixtures where name='configuration'),'cropFocusX',0.3,'volumePercent',28,'displayTitle','Stored title'))),312,35)$$,'rich dynamic placement and screen theme are saved together');
reset role;
insert into command_results values('rich-snapshot',private.build_playlist_authoring_snapshot(pg_temp.uid(35))),('rich-release',to_jsonb(private.materialize_playlist_configuration_s185(pg_temp.uid(35))));
select is((select value#>>'{items,0,dynamicSelectionMode}'from command_results where name='rich-snapshot'),'latest','authoring snapshot preserves live selection policy');
select is((select value#>>'{items,0,dynamicSnapshotId}'from command_results where name='rich-snapshot'),pg_temp.uid(302)::text,'snapshot preserves the actually reviewed immutable data');
select is((select value#>'{items,0,sitesConfiguration}'from command_results where name='rich-snapshot'),(select document from typed_fixtures where name='configuration'),'authoring snapshot retains exact screen theme');
set local role authenticated;
insert into command_results values('rich-duplicate',to_jsonb(public.duplicate_playlist_draft_v1(pg_temp.uid(35),'Duplicated rich playlist')));
select ok((select dynamic_slide_id=pg_temp.uid(301)and dynamic_snapshot_id=pg_temp.uid(302)and dynamic_selection_mode='latest'and sites_configuration_json=(select document from typed_fixtures where name='configuration')and crop_focus_x=0.3 and volume_percent=28 from public.playlist_items where playlist_id=((select value from command_results where name='rich-duplicate')#>>'{}')::uuid),'playlist duplicate retains bindings, policy, theme, crop and audio');
insert into command_results values('template',public.create_tenant_playlist_template_v1(pg_temp.uid(35),'Reusable rich source','Actual saved source settings',pg_temp.uid(313)));
insert into command_results values('instance',public.instantiate_tenant_playlist_template_v1((select(value->>'templateId')::uuid from command_results where name='template'),'Instantiated rich source',pg_temp.uid(314)));
select ok((select dynamic_selection_mode='latest'and dynamic_snapshot_id=pg_temp.uid(302)and sites_configuration_json=(select document from typed_fixtures where name='configuration')and crop_focus_x=0.3 from public.playlist_items where playlist_id=(select(value->>'playlistId')::uuid from command_results where name='instance')),'template instantiation retains live policy and all stored rich settings');
select lives_ok($$select public.mutate_playlist_batch_v1((select(value->>'playlistId')::uuid from command_results where name='instance'),(select revision from public.playlists where id=(select(value->>'playlistId')::uuid from command_results where name='instance')),jsonb_build_array(jsonb_build_object('operation','patch','itemId',(select id from public.playlist_items where playlist_id=(select(value->>'playlistId')::uuid from command_results where name='instance')),'patch',jsonb_build_object('displayTitle','Later reviewed edit'))),pg_temp.uid(315))$$,'newly instantiated item can be edited normally');
select is(public.instantiate_tenant_playlist_template_v1((select(value->>'templateId')::uuid from command_results where name='template'),'Instantiated rich source',pg_temp.uid(314)),(select value from command_results where name='instance'),'retry returns the original template acknowledgement');
select is((select display_title from public.playlist_items where playlist_id=(select(value->>'playlistId')::uuid from command_results where name='instance')),'Later reviewed edit','template retry cannot overwrite subsequent edits');
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','patch','itemId',(select id from public.playlist_items where playlist_id=pg_temp.uid(35)),'patch',jsonb_build_object('displayTitle','Draft after publication','sitesConfiguration',null))),316,35)$$,'a later draft can change its rich fields');
insert into command_results values('restore-request',jsonb_build_object('revision',(select revision from public.playlists where id=pg_temp.uid(35))));
insert into command_results values('restore',public.restore_playlist_release_to_draft_v1(((select value from command_results where name='rich-release')#>>'{}')::uuid,(select(value->>'revision')::bigint from command_results where name='restore-request'),pg_temp.uid(317)));
select is((select value->>'outcome'from command_results where name='restore'),'restored','published rich source restores through guarded authoring');
select ok((select dynamic_selection_mode='latest'and dynamic_snapshot_id=pg_temp.uid(302)and sites_configuration_json=(select document from typed_fixtures where name='configuration')and display_title='Stored title'and crop_focus_x=0.3 and volume_percent=28 from public.playlist_items where playlist_id=pg_temp.uid(35)),'release restoration retains policy, binding, theme, crop, title and audio');
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','patch','itemId',(select id from public.playlist_items where playlist_id=pg_temp.uid(35)),'patch',jsonb_build_object('displayTitle','After restore'))),318,35)$$,'restored source remains editable');
select is(public.restore_playlist_release_to_draft_v1(((select value from command_results where name='rich-release')#>>'{}')::uuid,(select(value->>'revision')::bigint from command_results where name='restore-request'),pg_temp.uid(317)),(select value from command_results where name='restore'),'restore retry acknowledges its first result');
select is((select display_title from public.playlist_items where playlist_id=pg_temp.uid(35)),'After restore','restore retry preserves edits made after its acknowledgement');
reset role;
-- Historical releases may have no authoring snapshot: use their frozen placement contract.
insert into public.playlist_releases(id,tenant_id,playlist_id,version,manifest_hash,manifest_json,item_count,total_duration_seconds,total_bytes)values(pg_temp.uid(320),pg_temp.uid(10),pg_temp.uid(36),1,repeat('c',64),'{}',1,15,2048);
insert into public.playlist_release_items(tenant_id,playlist_id,release_id,media_asset_id,media_variant_id,sort_order,duration_seconds,fit_mode,muted,asset_kind,asset_title,storage_path,mime_type,file_size_bytes,checksum_sha256,dynamic_snapshot_id,live_data_enabled,sites_configuration_json)
select pg_temp.uid(10),pg_temp.uid(36),pg_temp.uid(320),asset.id,variant.id,0,15,'contain',true,'image','Historical source',variant.storage_path,variant.mime_type,variant.file_size_bytes,variant.checksum_sha256,pg_temp.uid(302),true,(select document from typed_fixtures where name='configuration')from public.media_assets asset join public.media_variants variant on variant.asset_id=asset.id where asset.id=pg_temp.uid(20);
set local role authenticated;
select lives_ok($$select public.restore_playlist_release_to_draft_v1(pg_temp.uid(320),0,pg_temp.uid(321))$$,'historical publication without authoring snapshot can restore');
select ok((select dynamic_selection_mode='latest'and dynamic_snapshot_id=pg_temp.uid(302)and sites_configuration_json=(select document from typed_fixtures where name='configuration')from public.playlist_items where playlist_id=pg_temp.uid(36)),'legacy history recovers bindings and screen theme from frozen release items');
reset role;
-- Two ordered current Studio members with actual immutable export and ready variants.
insert into public.studio_series(id,tenant_id,owner_user_id,name)values(pg_temp.uid(400),pg_temp.uid(10),pg_temp.uid(1),'Complete ready series');
insert into public.studio_projects(id,tenant_id,owner_user_id,name,orientation,width,height,motion_enabled,duration_ms)
select pg_temp.uid(n),pg_temp.uid(10),pg_temp.uid(1),'Series member '||n,'landscape',1920,1080,true,45000 from generate_series(401,402)n;
insert into public.studio_project_drafts(tenant_id,project_id,document_json,document_hash)select pg_temp.uid(10),pg_temp.uid(n),(select document from typed_fixtures where name='studio'),repeat('d',64)from generate_series(401,402)n;
insert into public.studio_revisions(id,tenant_id,project_id,revision_number,draft_revision,document_json,document_hash)select pg_temp.uid(n+10),pg_temp.uid(10),pg_temp.uid(n),1,0,(select document from typed_fixtures where name='studio'),repeat('d',64)from generate_series(401,402)n;
insert into public.studio_render_jobs(id,tenant_id,project_id,revision_id,status,output_kind,request_idempotency_key,request_hash,media_asset_id,progress,finished_at)
select pg_temp.uid(n+20),pg_temp.uid(10),pg_temp.uid(n),pg_temp.uid(n+10),'completed','png',pg_temp.uid(n+30),repeat('e',64),pg_temp.uid(case when n=401 then 20 else 22 end),100,now()from generate_series(401,402)n;
insert into public.studio_exports(id,tenant_id,project_id,revision_id,render_job_id,media_asset_id,output_kind,width,height,duration_seconds,checksum_sha256)
select pg_temp.uid(n+40),pg_temp.uid(10),pg_temp.uid(n),pg_temp.uid(n+10),pg_temp.uid(n+20),pg_temp.uid(case when n=401 then 20 else 22 end),'png',1920,1080,null,repeat('a',64)from generate_series(401,402)n;
insert into public.studio_series_items(tenant_id,series_id,project_id,sort_order)select pg_temp.uid(10),pg_temp.uid(400),pg_temp.uid(n),n-401 from generate_series(401,402)n;
insert into public.studio_series(id,tenant_id,owner_user_id,name,updated_at)
select pg_temp.uid(n),pg_temp.uid(10),pg_temp.uid(1),'Incomplete newer series '||n,now()+interval'1 day' from generate_series(500,508)n;
set local role authenticated;
select is((public.list_publisher_studio_series_v1(pg_temp.uid(10))->'series'->0->>'id'),pg_temp.uid(400)::text,'publisher Studio page reads the exact ready series');
select is(jsonb_array_length(public.list_publisher_studio_series_v1(pg_temp.uid(10))->'series'->0->'members'),2,'Studio library includes every current member');
select is((public.list_publisher_studio_series_v1(pg_temp.uid(10))->>'total')::integer,1,'ready library count excludes newer incomplete series before pagination');
select is(jsonb_array_length(public.list_publisher_studio_series_v1(pg_temp.uid(10))->'series'),1,'nine newer incomplete series cannot hide a verified whole series from the first page');
insert into command_results values('studio-add',pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_studio_series','clientId',pg_temp.uid(450),'clientItemIds',jsonb_build_array(pg_temp.uid(450),pg_temp.uid(451)),'seriesId',pg_temp.uid(400),'expectedSeriesRevision',1)),452,37));
select is((select count(*)from public.playlist_items where playlist_id=pg_temp.uid(37)),2::bigint,'one selection adds the whole ordered Studio series');
select is((select media_asset_id from public.playlist_items where playlist_id=pg_temp.uid(37)order by sort_order limit 1),pg_temp.uid(20),'first member keeps the saved series ordering');
select is((select value->'itemIds'->>pg_temp.uid(451)::text from command_results where name='studio-add'),(select id::text from public.playlist_items where playlist_id=pg_temp.uid(37)order by sort_order desc limit 1),'acknowledgement maps every temporary series identity to its database item');
insert into command_results values('studio-zone',public.create_studio_series_zone_playlist_v1(pg_temp.uid(400),1,pg_temp.uid(453)));
select is((select value->>'outcome'from command_results where name='studio-zone'),'created','complete current series can create a real zone playlist');
select is((select count(*)from public.playlist_release_items where playlist_id=(select(value->>'playlistId')::uuid from command_results where name='studio-zone')),2::bigint,'zone playlist publication freezes both current Studio members');
select is(public.create_studio_series_zone_playlist_v1(pg_temp.uid(400),1,pg_temp.uid(453)),(select value from command_results where name='studio-zone'),'zone playlist retry creates no duplicate playlist or release');
reset role;
update public.studio_project_drafts set draft_revision=1 where project_id=pg_temp.uid(402);
set local role authenticated;
select throws_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_studio_series','clientId',pg_temp.uid(460),'clientItemIds',jsonb_build_array(pg_temp.uid(460),pg_temp.uid(461)),'seriesId',pg_temp.uid(400),'expectedSeriesRevision',1)),462,38)$$,'23514',null,'an outdated later export rolls back the whole series selection');
select is((select count(*)from public.playlist_items where playlist_id=pg_temp.uid(38)),0::bigint,'failed second member cannot leave the first member behind');
select is((select revision from public.playlists where id=pg_temp.uid(38)),0::bigint,'incomplete series leaves playlist revision unchanged');
select is(jsonb_array_length(public.list_publisher_studio_series_v1(pg_temp.uid(10))->'series'),0,'incomplete current series is absent from ready picker');
select set_config('request.jwt.claim.sub',pg_temp.uid(2)::text,true);
select throws_ok($$select public.list_publisher_studio_series_v1(pg_temp.uid(10))$$,'42501',null,'tenant B cannot read tenant A Studio library');
select throws_ok($$select public.create_studio_series_zone_playlist_v1(pg_temp.uid(400),1,pg_temp.uid(463))$$,'42501',null,'tenant B cannot materialize tenant A Studio series');
reset role;

insert into public.dynamic_slide_snapshots(id,tenant_id,dynamic_slide_id,template_version_id,data_source_id,source_revision_hash,snapshot_data_json,status,output_media_asset_id,completed_at)
select pg_temp.uid(303),tenant_id,id,template_version_id,data_source_id,repeat('f',64),'{"type":"sport_standing","sport":{"title":"Later live source","items":[]}}','ready',pg_temp.uid(20),now()from public.dynamic_slides where id=pg_temp.uid(301);
update public.dynamic_slides set current_snapshot_id=pg_temp.uid(303)where id=pg_temp.uid(301);
update public.playlist_items set dynamic_selection_mode='pinned'where playlist_id=pg_temp.uid(35);
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
insert into command_results values('historical-copy',to_jsonb(public.duplicate_playlist_draft_v1(pg_temp.uid(35),'Historical reviewed source')));
select ok((select dynamic_snapshot_id=pg_temp.uid(302)and dynamic_selection_mode='pinned'from public.playlist_items where playlist_id=((select value from command_results where name='historical-copy')#>>'{}')::uuid),'duplicate retains the reviewed old snapshot and original selection mode after source changes');
reset role;
insert into public.playlist_sections(id,tenant_id,playlist_id,name,position_key,enabled,default_duration_seconds,default_transition,created_by,updated_by)values(pg_temp.uid(480),pg_temp.uid(10),pg_temp.uid(32),'Disabled but preserved section',4096,false,20,'wipe',pg_temp.uid(1),pg_temp.uid(1));
insert into public.playlist_items(tenant_id,playlist_id,media_asset_id,sort_order,position_key,duration_seconds,fit_mode,muted,section_id,enabled,crop_focus_y,background_color,visible_from,visible_until,accessibility_name)
select pg_temp.uid(10),pg_temp.uid(32),pg_temp.uid(22),n,n*1024+2048,15,'cover',false,pg_temp.uid(480),false,0.7,'#03438a',now(),now()+interval'1 day','Stored accessible name'from generate_series(0,1)n;
set local role authenticated;
insert into command_results values('sections-copy',to_jsonb(public.duplicate_playlist_draft_v1(pg_temp.uid(32),'Complete sections copy')));
select is((select count(*)from public.playlist_items where playlist_id=((select value from command_results where name='sections-copy')#>>'{}')::uuid),2::bigint,'duplicate keeps disabled placements in their saved order');
select ok((select bool_and(item.enabled=false and item.crop_focus_y=0.7 and item.background_color='#03438a'and item.visible_until is not null and item.accessibility_name='Stored accessible name'and section.enabled=false and section.default_duration_seconds=20 and section.default_transition='wipe')from public.playlist_items item join public.playlist_sections section on section.id=item.section_id and section.tenant_id=item.tenant_id where item.playlist_id=((select value from command_results where name='sections-copy')#>>'{}')::uuid),'duplicate preserves section membership, visibility, crop, accessibility and section defaults');
select ok((select default_fit_mode='cover'and default_transition='crossfade'and default_video_muted=false and default_background_color='#03438a'from public.playlists where id=((select value from command_results where name='sections-copy')#>>'{}')::uuid),'duplicate retains the original playlist defaults');
reset role;
select *from finish();rollback;
